def _recipe(kind, style, desc):
    """(positive prompt, denoise, negative prompt) for a scene.

    `kind` picks the CANVAS construction and is the coarse choice; `style` is an optional
    per-scene override of the prompt only, for masters whose geometry the generic recipe
    describes wrongly. Kept as one function so the three values can never drift apart and
    so the cache digest has a single thing to hash.
    """
    if kind == "object":
        return POS_OBJ, OBJ_DENOISE, NEG_OBJ
    if style == "inclined_disc":
        return POS_DISC.format(desc=desc), DISC_DENOISE, NEG_DISC
    if style:
        raise ValueError(f"unknown prompt style {style!r}")
    return POS_TMPL.format(desc=desc), OUTPAINT_DENOISE, NEG


